import {mountVideo} from './video-ui.js';
import {PLATFORM_INFO,PLATFORM_NAMES} from './platforms.js';
import {openFeishu} from './feishu-ui.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=PLATFORM_NAMES,statusNames={queued:'等待中',running:'采集中',stopping:'正在暂停',paused:'已暂停',completed:'已完成',partial:'部分完成',blocked:'待处理',failed:'未完成'};
const mainViewKey='current-main-view';
function storedMainView(){try{const view=localStorage.getItem(mainViewKey);return ['dashboard','tasks','videos'].includes(view)?view:'';}catch{return '';}}
function rememberMainView(view){const main={dashboard:'dashboard',connections:'dashboard',tasks:'tasks',videos:'videos',subtitles:'videos',covers:'videos',translation:'videos'}[view];if(main)try{localStorage.setItem(mainViewKey,main);}catch{}}
const state={view:storedMainView()||((new URLSearchParams(location.search).has('task')||new URLSearchParams(location.search).has('desktop'))?'dashboard':'videos'),keywordQuery:'',keywordPage:1,tasksPage:1,tasks:[],connections:{},selected:new URLSearchParams(location.search).get('task')||localStorage.getItem('selected-task')||'',result:null,filters:{},page:1,mode:'links',busy:false,request:0};
const hiddenKeywordKey='hidden-keyword-tasks';
let hiddenKeywords;try{hiddenKeywords=new Set(JSON.parse(localStorage.getItem(hiddenKeywordKey)||'[]'));}catch{hiddenKeywords=new Set();}
function saveHiddenKeywords(){localStorage.setItem(hiddenKeywordKey,JSON.stringify([...hiddenKeywords]));}
const number=v=>`<span data-count="${Number(v||0)}">${Number(v||0).toLocaleString('zh-CN')}</span>`;const date=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'时间未提供';
function tag(p){return `<span class="tag ${p==='douyin'?'dy':p==='xiaohongshu'?'xhs':''}">${names[p]||'未标注'}</span>`;}
function badge(s){return `<span class="tag ${s==='completed'?'ok':s==='running'?'':'warn'}">${s==='running'?'<i class="active-dot"></i>':''}${statusNames[s]||esc(s)}</span>`;}
function commentPageNumbers(page,pages){const count=Math.min(5,pages),start=Math.min(Math.max(1,page-Math.floor(count/2)),Math.max(1,pages-count+1));return Array.from({length:count},(_,i)=>{const value=start+i;return `<button class="button small page-number ${value===page?'active':''}" data-action="comment-page" data-page="${value}" ${value===page?'aria-current="page"':''}>${value}</button>`;}).join('');}
async function api(url,data){const r=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const b=await r.json();if(!r.ok)throw new Error(b.error||'请求失败');return b;}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function params(){return new URLSearchParams(Object.entries({...state.filters,page:state.page}).filter(([,v])=>v!==undefined&&v!==null&&v!==''&&v!==false));}
async function refresh(){const data=await api('/api/state');state.tasks=data.tasks;state.connections=data.connections;state.active=data.active;state.activeTaskIds=data.activeTaskIds||[data.active].filter(Boolean);state.maxConcurrent=data.maxConcurrent||1;state.engines=data.engines;if($('#task-count'))$('#task-count').textContent=state.tasks.length;if(!state.tasks.some(t=>t.id===state.selected))state.selected=state.tasks[0]?.id||'';}
async function loadResult(){if(!state.selected){state.result=null;return;}const request=++state.request,id=state.selected;const r=await api(`/api/tasks/${id}?${params()}`);if(request===state.request&&id===state.selected){state.result=r;state.page=r.page;}}
function title(eyebrow,h,sub,action=true){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${h}</h1><p class="subtitle">${sub}</p></div>${action?'<button class="button primary" data-action="new"><span>＋</span> 新建分析</button>':''}</div>`;}
function emptyDashboard(){return `${title('LISTEN. UNDERSTAND. CREATE.','从评论里，找到下一条内容。','把零散的声音，整理成清晰的创作方向。')}<section class="welcome"><div><div class="section-kicker">YOUR NEXT IDEA STARTS HERE</div><h2>用户真正想要的，<br>往往就在评论区。</h2><p>输入作品链接，发现问题、需求和内容机会。</p><div class="actions"><button class="button primary" data-action="new">开始第一次分析 <span>↗</span></button><button class="button ghost" data-action="demo">体验演示数据 →</button></div></div><div class="welcome-art" aria-hidden="true"><div class="bubble three">✳</div><div class="bubble one">“新手应该怎么选？”</div><div class="bubble two">发现一个值得回答的问题 ↗</div></div></section><div class="starter-grid"><button class="starter-card" data-action="new" data-mode="links"><span class="step">01 / 精准采集</span><strong>分析一个评论区</strong><p>支持抖音、小红书等 7 个平台</p><span class="arrow">↗</span></button><button class="starter-card" data-action="new" data-mode="search"><span class="step">02 / 拓展视野</span><strong>围绕关键词找内容</strong><p>连接平台后，发现相关作品与讨论</p><span class="arrow">↗</span></button><button class="starter-card" data-action="new" data-mode="creator"><span class="step">03 / 创作者研究</span><strong>分析创作者主页</strong><p>采集指定创作者作品下的评论</p><span class="arrow">↗</span></button></div><section class="panel"><div class="section-head"><h2>最近的分析</h2><span class="tag">本地保存</span></div><div class="empty"><div class="empty-icon">⌁</div><h3>你的第一份洞察，正在等你开始</h3><p>分析结果会保留原始评论和来源，让每一个判断都有依据。</p></div></section>`;}
function keywordMatches(){const q=state.keywordQuery.trim().toLocaleLowerCase();return state.tasks.filter(t=>t.mode==='search'&&!hiddenKeywords.has(t.id)&&(!q||`${t.options.query||''} ${t.name}`.toLocaleLowerCase().includes(q)));}
function keywordPagination(){const total=keywordMatches().length,pages=Math.max(1,Math.ceil(total/5));state.keywordPage=Math.min(Math.max(1,state.keywordPage),pages);return `<span>共 ${total} 条 · ${state.keywordPage} / ${pages} 页</span><button class="button small" data-action="keyword-prev" ${state.keywordPage<=1?'disabled':''}>← 上一页</button><button class="button small" data-action="keyword-next" ${state.keywordPage>=pages?'disabled':''}>下一页 →</button>`;}
function keywordResults(){const all=keywordMatches();state.keywordPage=Math.min(Math.max(1,state.keywordPage),Math.max(1,Math.ceil(all.length/5)));const tasks=all.slice((state.keywordPage-1)*5,state.keywordPage*5);return tasks.length?tasks.map(t=>`<div class="keyword-item ${t.id===state.selected?'keyword-selected':''}" data-keyword-id="${t.id}"><button class="keyword-choice" data-action="open-task" data-id="${t.id}" aria-pressed="${t.id===state.selected}">${esc(t.options.query||t.name)} · ${number(t.count)} 条 · ${esc(statusNames[t.status]||t.status)}</button><div class="keyword-operations"><button data-action="${t.status==='running'?'pause':'continue-task'}" data-id="${t.id}" ${t.status==='stopping'?'disabled':''}>${t.status==='running'?'暂停采集':t.status==='stopping'?'正在暂停…':'继续采集'}</button><button data-nav="connections">数据连接</button><button data-action="remove-keyword" data-id="${t.id}" title="从此列表删除，任务和评论仍保留在我的任务">删除</button></div></div>`).join(''):'<span class="help">没有匹配的关键词任务，可新建采集或从「我的任务」重新打开。</span>';}
function keywordPicker(){const task=state.result.task;return `<section class="panel keyword-picker" aria-label="按采集关键词查看数据"><div class="keyword-heading"><h2>按采集关键词查看</h2><input id="keyword-task-search" aria-label="查找采集关键词" placeholder="输入采集关键词或任务名称" value="${esc(state.keywordQuery)}"><button class="button small" data-action="new" data-mode="search">＋ 新建关键词采集</button></div><div id="keyword-task-results" class="keyword-results">${keywordResults()}</div><div class="keyword-current" data-task-id="${task.id}"><div class="grow"><span class="help">当前查看</span><strong>${esc(task.name)}</strong><span class="help">更新于 ${date(task.updated_at)}</span></div><span class="keyword-count">已采集 <b>${number(task.count)}</b> 条评论</span>${badge(task.status)}${task.message?`<details class="keyword-progress"><summary>进度详情</summary><p>累计读取（含重复）：${number(task.received??task.processed??task.count)} 条 · 去重保存：${number(task.count)} 条${task.received_legacy?'；历史重复读取未完整记录，此为已记录数量':''}</p><p>每作品采集：${task.options.maxComments==null?'所有可读取评论（不设条数上限）':task.options.maxComments+' 条上限'}；已获取评论为本机保存样本，不等于平台显示总数。</p><p>${esc(task.message)}</p>${(state.result.sources||[]).map(s=>`<p>${esc(names[s.platform]||s.platform)} · ${s.count} 条 · ${esc(s.message)}</p>`).join('')}</details>`:''}<div id="keyword-pagination" class="keyword-pagination" aria-label="关键词分页">${keywordPagination()}</div></div></section>`;}
function dashboard(){if(!state.result)return emptyDashboard();const {task,analysis:a,comments,sources,matched,page,pages}=state.result;
const max=a.keywords[0]?.comments||1;
return `${title('KK-Tiong_Pavelio','把用户的声音，变成创作线索。','看见高频问题，也看见它背后的真实需求。')}
${keywordPicker()}
${task.mode==='demo'?'<div class="notice">演示模式 · 以下评论为人工编写，用于体验功能，不代表两平台真实数据。<button class="button small ghost" data-action="new">分析我的评论 →</button></div>':''}
<div class="metrics"><div class="metric" role="button" tabindex="0" data-action="metric-filter" data-scope="all"><div class="metric-label">已获取评论<span>▤</span></div><strong>${number(a.total)}</strong><small>${task.mode==='demo'?'人工演示样本':'去重后保留的原始记录'}</small></div><div class="metric" role="button" tabindex="0" data-action="metric-filter" data-scope="valid"><div class="metric-label">纳入分析<span>◈</span></div><strong>${number(a.valid)}</strong><small>已按当前条件过滤 ${number(a.filtered)} 条</small></div><div class="metric" role="button" tabindex="0" data-action="metric-filter" data-scope="posts"><div class="metric-label">涉及作品<span>▧</span></div><strong>${number(a.posts)}</strong><small>${a.byPlatform.filter(p=>p.count).map(p=>`${names[p.platform]} ${number(p.count)} 条`).join(' · ')||'等待评论数据'}</small></div><div class="metric" role="button" tabindex="0" data-action="metric-filter" data-scope="needs"><div class="metric-label">需求线索<span>⌁</span></div><strong>${number(a.topics.filter(t=>t.count>0).length)}</strong><small>本地规则分类 · 点击查看证据</small></div></div>
<div class="two-col insight-panels"><section class="panel"><div class="section-head"><div><div class="section-kicker">WHAT PEOPLE TALK ABOUT</div><h2>大家在讨论什么</h2></div><div class="actions keyword-export-actions"><button class="button small" data-action="export-keywords" aria-label="导出关键词">↓ 关键词</button><button class="button small" data-action="export-wordcloud">↓ 关键词词云</button></div></div><p class="panel-heading-note">同义词合并 · 点选关键词查看原文</p>${a.keywords.length?`<div class="insight-list">${a.keywords.slice(0,8).map((k,i)=>`<button class="bar-row" data-action="keyword" data-word="${esc(k.word)}" title="${k.occurrences} 次出现 / ${k.posts} 个作品"><span class="rank">${String(i+1).padStart(2,'0')}</span><span>${esc(k.word)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,k.comments/max*100)}%"></div></div><span class="bar-number">${number(k.comments)}</span></button>`).join('')}</div>`:'<div class="empty"><p>获取评论后，这里将显示高频关键词</p></div>'}${a.watch.length?`<div class="watch-row"><span class="muted" style="font-size:10px">关注词</span>${a.watch.map(w=>`<button class="tag" data-action="watch" data-word="${esc(w.word)}">${esc(w.word)} <b>${number(w.count)}</b></button>`).join('')}</div>`:''}</section>
<section class="panel hot-comments"><div class="section-head"><div><div class="section-kicker">MOST LIKED COMMENTS</div><h2>Top 5 热评</h2></div></div><p class="panel-heading-note">按已获取评论点赞排序 · 点击查看原文</p><div class="insight-list">${(state.result.hotComments||[]).length?state.result.hotComments.slice(0,5).map((c,i)=>`<button class="hot-comment" data-action="hot-detail" data-index="${i}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="hot-text">${esc(c.text)}</span><span class="hot-likes">♡ ${number(c.likes)}</span><span class="row-progress" aria-hidden="true"><i style="width:${c.likes/Math.max(1,state.result.hotComments[0]?.likes||0)*100}%"></i></span></button>`).join(''):'<p class="help">获取评论后显示点赞最高的5条评论</p>'}</div></section>
<section class="panel"><div class="section-head"><div><div class="section-kicker">FROM COMMENTS TO IDEAS</div><h2>值得回应的用户需求</h2></div><button class="button small" data-action="reply-settings">自动回复</button></div><p class="panel-heading-note">按匹配评论数量展示 · 点击查看证据</p><div class="insight-list">${a.topics.map((t,i)=>`<button class="topic" data-action="category" data-category="${t.name}"><span class="topic-icon">${['?','⌁','¥','⇄','▧'][i]}</span><span class="topic-text"><strong>${t.name}</strong><p>${esc(t.count?t.suggestion:'当前样本中暂无匹配评论')}</p></span><span class="topic-count">${number(t.count)} 条 ↗</span><span class="row-progress" aria-hidden="true"><i style="width:${t.count/Math.max(1,...a.topics.map(x=>x.count))*100}%"></i></span></button>`).join('')}</div><p class="help">规则建议，不是事实结论；一条评论可归入多个需求。</p></section></div>
<section class="panel" id="comments-panel"><div class="section-head"><div><h2>回到评论现场 <span class="pill-count">${number(matched)}</span></h2><p class="help">点击正文看上下文，收藏值得跟进的声音。</p></div><div class="actions"><select id="export-type" aria-label="导出格式"><option value="xlsx">Excel</option><option value="csv">CSV</option><option value="json">JSON</option><option value="feishu">飞书多维表格</option></select><button class="button small" data-action="export">↓ 导出</button></div></div>
<div class="toolbar"><div class="searchbox"><span>⌕</span><input id="comment-search" value="${esc(state.filters.q||'')}" placeholder="搜索评论内容，按 Enter 筛选" aria-label="搜索评论"></div><select id="platform-filter" aria-label="筛选平台"><option value="">全部平台</option>${[...PLATFORM_INFO.map(p=>p.id),'unknown'].map(p=>`<option value="${p}" ${state.filters.platform===p?'selected':''}>${names[p]}</option>`).join('')}</select><select id="category-filter" aria-label="筛选需求"><option value="">全部需求</option>${a.topics.map(t=>`<option ${state.filters.category===t.name?'selected':''}>${t.name}</option>`).join('')}</select><label class="checkbox"><input id="favorite-filter" type="checkbox" ${state.filters.favorite?'checked':''}>只看收藏</label></div>
${state.filters.scope?`<div class="filter-chip">${{all:'全部已获取评论',valid:'纳入分析的评论',posts:'有作品标识的评论',needs:'匹配需求的评论'}[state.filters.scope]}<button data-action="clear-scope" aria-label="清除统计筛选">×</button></div>`:''}
${state.filters.word||state.filters.q?`<div class="actions" style="margin-bottom:10px"><span class="filter-chip">${esc(state.filters.word?'关键词：'+state.filters.word:'搜索：'+state.filters.q)}<button data-action="clear-filter" aria-label="清除关键词">×</button></span></div>`:''}
<div class="table-wrap"><table><thead><tr><th style="width:80px">平台</th><th>评论原文</th><th>需求分类</th><th style="width:55px">点赞</th><th style="width:40px">收藏</th></tr></thead><tbody>${comments.map((c,i)=>`<tr><td>${tag(c.platform)}</td><td class="comment-cell"><button class="comment-text" data-action="detail" data-index="${i}">${esc(c.text)}</button><div class="comment-meta">${esc(c.title||'作品标题未提供')} · ${date(c.created_at)} ${c.parent_id?'· 回复评论':''}</div></td><td><span class="tag">${esc(c.category||'其他讨论')}</span></td><td class="num">${number(c.likes)}</td><td><button class="favorite ${c.favorite?'on':''}" data-action="favorite" data-index="${i}" aria-label="${c.favorite?'取消收藏':'收藏评论'}">${c.favorite?'★':'☆'}</button></td></tr>`).join('')}</tbody></table>${!comments.length?'<div class="empty"><h3>当前没有匹配的评论</h3><p>可以调整筛选条件，或添加评论数据。</p></div>':''}</div><div class="pagination"><span>共 ${number(matched)} 条 · 第 ${page} / ${pages} 页</span><div class="actions comment-pages"><button class="button small" data-action="prev" ${page<=1?'disabled':''}>← 上一页</button><span class="page-numbers" aria-label="评论页码">${commentPageNumbers(page,pages)}</span><button class="button small" data-action="next" ${page>=pages?'disabled':''}>下一页 →</button></div></div></section>
<details id="scope-details"><summary>采集范围与分析口径 ${sources.length?'· '+sources.length+' 个来源':''}</summary><section class="panel"><p>当前结果仅代表已获取样本，不能推断为平台全量。分词统计中的评论数按每条评论计一次；作品数只计有作品标识的记录。</p><p class="help">${esc(task.message)} · 未提供时间 ${a.unknownDates} 条 · 疑似推广／无文本 ${a.noise} 条</p><label class="checkbox"><input id="noise-filter" type="checkbox" ${state.filters.noise?'checked':''}>纳入疑似推广与无效文本</label>${sources.map(s=>`<div class="source-row">${tag(s.platform)}<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.url.split('?')[0])}<p>${esc(s.message)}</p></a><span class="tag">${number(s.count)} 条 · ${({complete:'分页结束',limit:'达到上限',partial:'部分读取',blocked:'待处理',pending:'待采集',running:'采集中',stopping:'正在暂停'})[s.status]}</span></div>`).join('')}<p class="help">${esc(a.engine)}；情绪结果仅供参考。无平台评论 ID 时使用内容、作品、作者和时间生成指纹去重，信息缺失可能合并相同记录。</p></section></details>`;}
function tasksView(){const pageSize=15,pages=Math.max(1,Math.ceil(state.tasks.length/pageSize));state.tasksPage=Math.max(1,Math.min(state.tasksPage,pages));const visibleTasks=state.tasks.slice((state.tasksPage-1)*pageSize,state.tasksPage*pageSize);return `<button class="button small connection-back" data-nav="dashboard">← 返回洞察工作台</button>${title('YOUR RESEARCH LIBRARY','每一次倾听，都有迹可循。',`任务和原始评论自动保存在本机。当前 ${state.activeTaskIds?.length||0} / ${state.maxConcurrent||3} 个任务正在采集，可分别暂停。`)}${state.tasks.length?visibleTasks.map(t=>`<article class="task-card"><span class="topic-icon">${t.mode==='import'?'↓':t.mode==='demo'?'◈':'⌕'}</span><div class="grow"><h3>${esc(t.name)}</h3><p>${date(t.updated_at)} · ${number(t.count)} 条评论 · ${t.mode==='demo'?'人工演示':t.mode==='import'?'文件导入':'平台采集'}</p></div>${badge(t.status)}<div class="actions"><button class="button small" data-action="continue-task" data-id="${t.id}" title="${['links','search','creator'].includes(t.mode)?'沿用原条件补采，新评论自动去重并纳入分析':'演示或历史导入任务没有平台采集来源'}" ${!['links','search','creator'].includes(t.mode)||state.activeTaskIds?.includes(t.id)||['running','stopping'].includes(t.status)?'disabled':''}>${t.status==='running'?'采集中':t.status==='stopping'?'正在暂停…':'继续采集分析'}</button>${t.status==='running'?`<button class="button small" data-action="pause" data-id="${t.id}">暂停</button>`:''}<button class="button small" data-action="open-task" data-id="${t.id}">查看洞察 →</button></div></article>`).join('')+`<div class="pagination" aria-label="任务分页"><span>共 ${number(state.tasks.length)} 个任务 · 每页 15 条 · 第 ${state.tasksPage} / ${pages} 页</span><div class="actions"><button class="button small" data-action="tasks-prev" ${state.tasksPage<=1?'disabled':''}>← 上一页</button><button class="button small" data-action="tasks-next" ${state.tasksPage>=pages?'disabled':''}>下一页 →</button></div></div>`:'<section class="panel"><div class="empty"><h3>还没有分析任务</h3><p>从作品链接、关键词或创作者主页开始。</p><button class="button primary" data-action="new">新建分析</button></div></section>'}`;}
function connectionsView(){return `<button class="button small connection-back" data-nav="dashboard">← 返回洞察工作台</button>${title('DATA CONNECTIONS','连接你想听见的平台。','在独立浏览器中登录，正常读取页面已加载的评论。',false)}<div class="connection-grid">${PLATFORM_INFO.map(({id:p})=>{const c=state.connections[p]||{};return `<section class="panel connection-card"><div class="connection-logo platform-icon" aria-label="${names[p]}图标">${platformIcon(p)}</div><h2>${names[p]}</h2><span class="tag ${c.state==='verified'?'ok':'warn'}">${({unverified:'尚未验证',opened:'浏览器已打开',verified:'曾成功读取',closed:'浏览器已关闭',attention:'需要处理'})[c.state]||'尚未连接'}</span><p>${esc(c.message||'打开采集浏览器，完成平台登录后再开始任务。')}</p><button class="button primary" data-action="connect" data-platform="${p}">打开${names[p]}采集浏览器 ↗</button></section>`;}).join('')}</div><section class="panel connection-note"><div class="section-head"><h2>连接后，按正常使用平台的方式操作</h2></div><div class="note-list"><b>01</b> 在新打开的浏览器里扫码登录，不需要把密码或 Cookie 发给任何人。<br><b>02</b> 如遇验证，在平台页面手动完成；工作台会保留已采集的数据。<br><b>03</b> 回到工作台新建任务，或点击「继续采集」。<br><b>04</b> 平台没有提供可读取评论时，请检查登录状态或更换作品链接。</div><p class="help">登录后若搜索仍为空，可先分析具体作品链接。遇到验证码，请在平台页面处理后继续。登录资料仅保存在本机独立浏览器配置中。</p></section>`;}
let commentsObserver=null,lastCommentsEntrance='';
function animateComments(){
 commentsObserver?.disconnect();commentsObserver=null;
 const body=document.querySelector('#comments-panel tbody');
 if(!body){lastCommentsEntrance='';return;}
 const signature=JSON.stringify([state.selected,state.page,state.filters,state.result.comments.map(c=>c.key)]);
 if(!body.rows.length||signature===lastCommentsEntrance||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 body.classList.add('comments-stagger');
 [...body.rows].forEach((row,i)=>row.style.setProperty('--entry-delay',`${i*65}ms`));
 commentsObserver=new IntersectionObserver(entries=>{if(!entries.some(e=>e.isIntersecting))return;body.classList.add('comments-stagger-play');lastCommentsEntrance=signature;commentsObserver?.disconnect();commentsObserver=null;},{threshold:0});
 commentsObserver.observe(body);
}
function render(){globeCleanup?.();globeCleanup=null;const active=document.activeElement?.id;const selection=active==='comment-search'?document.activeElement.selectionStart:null;const draft=$('#comment-search')?.value,scope=$('#scope-details')?.open,format=$('#export-type')?.value;$('#page-name').textContent={dashboard:'洞察工作台',tasks:'我的任务',connections:'数据连接',videos:'视频 / 全网视频下载',subtitles:'字幕 / 字幕提取',covers:'封面 / 封面生成器',translation:'翻译'}[state.view];document.querySelectorAll('nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.view));document.body.classList.toggle('compact-video',state.view==='videos'||state.view==='subtitles');const mediaView=['videos','subtitles','covers','translation'].includes(state.view);$('#main').hidden=mediaView;$('#video-workspace').hidden=!mediaView;if(mediaView){document.querySelector('.media-menu button').classList.add('active');mountVideo($('#video-workspace'),state.view);return;}$('#main').innerHTML=state.view==='tasks'?tasksView():state.view==='connections'?connectionsView():dashboard();if(state.view==='dashboard'){const heading=$('#main>.title-row');if(heading){const action=heading.querySelector('[data-action=new]');const group=document.createElement('div');group.className='actions dashboard-actions';group.innerHTML='<button class="button" data-nav="connections">数据连接</button>';if(action)group.append(action);group.insertAdjacentHTML('beforeend','<button class="button" data-nav="tasks">我的任务</button>');heading.append(group);heading.classList.add('dashboard-heading');mountDigitalGlobe(heading);}}decorateMetrics();animateComments();animateInsights();if($('#scope-details')&&scope)$('#scope-details').open=true;if($('#export-type')&&format)$('#export-type').value=format;if(active==='comment-search'&&$('#comment-search')){$('#comment-search').value=draft;$('#comment-search').focus();$('#comment-search').setSelectionRange(selection,selection);}}
async function showTask(id){hiddenKeywords.delete(id);saveHiddenKeywords();state.selected=id;localStorage.setItem('selected-task',id);const url=new URL(location.href);url.searchParams.set('task',id);history.replaceState(null,'',url);state.view='dashboard';rememberMainView(state.view);state.filters={};state.page=1;await refresh();await loadResult();render();}
async function filtered(){state.page=1;await loadResult();render();}
function modal(mode='links'){state.engine='browser';state.mode=['links','search','creator'].includes(mode)?mode:'links';if(state.mode==='creator')state.engine='mediacrawler';modalContent();$('#task-modal').showModal();}
function modalContent(){const m=state.mode;$('#modal-body').innerHTML=`<form id="task-form"><div class="modal-content"><div class="tabs">${[['links','作品链接'],['search','关键词搜索'],['creator','创作者主页']].map(([k,n])=>`<button type="button" data-action="mode" data-mode="${k}" class="${m===k?'active':''}">${n}</button>`).join('')}</div><label class="field">采集方式<select name="engine" id="engine-select"><option value="mediacrawler" ${state.engine==='mediacrawler'?'selected':''} ${state.engines?.mediacrawler?.ready?'':'disabled'}>增强采集 · MediaCrawler · 7个平台</option><option value="browser" ${state.engine==='browser'?'selected':''} ${m==='creator'?'disabled':''}>页面采集 · 抖音 / 小红书</option></select></label><p class="help">增强采集支持作品、搜索、主页和二级回复。</p><label class="field">任务名称 <span class="muted">（可选）</span><input name="name" list="platform-suggestions" autocomplete="off" maxlength="100" placeholder="例如：AI 视频工具 · 用户需求"></label><datalist id="platform-suggestions"></datalist><p id="suggestion-status" class="help" role="status"></p><label class="field">${m==='creator'?'创作者主页链接':m==='links'?'作品分享链接':'搜索关键词'}<textarea name="input" placeholder="${m==='creator'?'粘贴创作者主页完整链接，每行一位':m==='links'?'粘贴平台作品分享链接，每行一个作品':'例如：AI 视频工具'}" required></textarea></label>${m==='search'?`<div class="platform-checks" style="flex-wrap:wrap">${PLATFORM_INFO.map(p=>`<label><input type="checkbox" name="platform" value="${p.id}" ${state.engine==='mediacrawler'||['douyin','xiaohongshu'].includes(p.id)?'checked':'disabled'}> ${p.name}</label>`).join('')}</div>`:''}<p class="help">${m==='search'?'搜索结果取决于平台可见范围，需要先在「数据连接」中完成登录。':'仅采集页面可读取的评论。遇到登录或验证时，可处理后继续。'}</p><label class="checkbox"><input type="checkbox" name="includeReplies" checked> 包含二级回复（增强采集）</label><details><summary>更多设置 · 关注词、排除词、采样范围</summary><label class="field">关注关键词<input name="watch" placeholder="价格,新手,教程（用逗号分隔）"></label><label class="field">不纳入分析的词<input name="exclude" placeholder="返利,代刷"></label><div class="fields-row"><label class="field">评论开始日期<input type="date" name="since"></label><label class="field">评论结束日期<input type="date" name="until"></label></div><p class="help">日期筛选只影响分析，原始评论仍保留；无法确定时间的评论不进入指定日期范围。</p><div class="fields-row"><label class="field">最多采集作品数<input type="number" name="maxPosts" min="1" max="30" value="10"></label><p class="help">每个作品采集所有可读取评论，不设条数上限；分页结束、暂停或平台阻碍时停止。</p></div></details><div id="form-error" class="form-error" role="alert"></div></div><div class="modal-footer"><span class="help">数据保存在你的电脑</span><button type="submit" class="button primary" id="submit-task">开始采集 →</button></div></form>`;}
async function submit(form){const data=new FormData(form);const opts=Object.fromEntries(['watch','exclude','since','until','maxPosts','maxComments'].map(k=>[k,data.get(k)||'']));opts.includeReplies=data.get('includeReplies')==='on';const result=await api('/api/tasks',{name:data.get('name'),mode:state.mode,engine:data.get('engine'),input:data.get('input'),platforms:data.getAll('platform'),options:opts});$('#task-modal').close();await showTask(result.task.id);toast('采集任务已启动，可在这里查看进度');}
function detail(index,hot=false){const c=(hot?state.result.hotComments:state.result.comments)[index];if(!c)return;$('#detail-body').innerHTML=`<div class="detail-content">${tag(c.platform)} ${state.result.task.mode==='demo'?'<span class="tag warn">人工演示评论</span>':''}<p class="quote">${esc(c.text)}</p>${c.parent_id?`<div class="parent-quote">回复上下文：${esc(c.parent_text||'上级评论尚未采集；这条回复需要结合原页面理解。')}</div>`:''}<div class="detail-grid"><div><small>作品</small>${esc(c.title||'未提供标题')}</div><div><small>评论时间</small>${date(c.created_at)}</div><div><small>需求分类 · 本地规则</small>${esc(c.category||'其他讨论')}</div><div><small>情绪参考</small>${esc(c.sentiment)}</div><div><small>点赞数</small>${number(c.likes)}</div><div><small>去重依据</small>${esc(c.identity)}</div></div>${c.source_url?`<a class="button primary" href="${esc(c.source_url)}" target="_blank" rel="noopener noreferrer">打开原作品 ↗</a>`:'<p class="help">这条评论未提供来源链接，不能跳转原作品。</p>'}</div>`;$('#detail-modal').showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-nav]');if(!b||b.disabled)return;try{if(b.dataset.nav){state.view=b.dataset.nav;rememberMainView(state.view);await refresh();if(state.view==='dashboard')await loadResult();render();return;}const action=b.dataset.action;
if(action==='new')modal(b.dataset.mode||'links');
else if(action==='hot-detail'){detail(+b.dataset.index,true);}
else if(action==='metric-filter'){state.filters={...(b.dataset.scope==='all'?{}:{platform:state.filters.platform,noise:state.filters.noise}),scope:b.dataset.scope};state.page=1;await loadResult();render();$('#comments-panel').scrollIntoView({behavior:'smooth',block:'start'});}
else if(action==='reply-settings')await openReplySettings();
else if(action==='close-modal')$('#task-modal').close();else if(action==='close-detail')$('#detail-modal').close();
else if(action==='mode'){state.mode=b.dataset.mode;if(state.mode==='creator')state.engine='mediacrawler';modalContent();}
else if(action==='demo'){b.disabled=true;const r=await api('/api/demo',{});await showTask(r.task.id);}
else if(action==='keyword-prev'||action==='keyword-next'){state.keywordPage+=action==='keyword-next'?1:-1;$('#keyword-task-results').innerHTML=keywordResults();$('#keyword-pagination').innerHTML=keywordPagination();}
else if(action==='remove-keyword'){hiddenKeywords.add(b.dataset.id);saveHiddenKeywords();render();toast('已从关键词列表删除；任务和评论保留，可在「我的任务」重新打开');}
else if(action==='open-task')await showTask(b.dataset.id);
else if(action==='keyword'||action==='watch'||action==='category'){state.filters.word=action==='keyword'?b.dataset.word:'';state.filters.q=action==='watch'?b.dataset.word:'';state.filters.category=action==='category'?b.dataset.category:'';await filtered();$('#comments-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}
else if(action==='clear-scope'){delete state.filters.scope;await filtered();}
else if(action==='clear-filter'){delete state.filters.word;delete state.filters.q;await filtered();}
else if(action==='tasks-prev'||action==='tasks-next'){state.tasksPage+=action==='tasks-next'?1:-1;render();$('#main').scrollIntoView({block:'start'});}
else if(action==='prev'||action==='next'){state.page+=action==='next'?1:-1;await loadResult();render();$('#comments-panel').scrollIntoView({block:'start'});}
else if(action==='comment-page'){state.page=Number(b.dataset.page)||1;await loadResult();render();$('#comments-panel').scrollIntoView({block:'start'});}
else if(action==='favorite'){const c=state.result.comments[+b.dataset.index];await api(`/api/tasks/${state.selected}/favorite`,{key:c.key,on:!c.favorite});await loadResult();render();}
else if(action==='detail')detail(+b.dataset.index);
else if(action==='export-wordcloud'){const p=params();p.set('kind','wordcloud');location.href=`/api/tasks/${state.selected}/export?${p}`;}
else if(action==='export-keywords'){const p=params();p.set('format','xlsx');p.set('kind','keywords');location.href=`/api/tasks/${state.selected}/export?${p}`;}
else if(action==='export'&&$('#export-type').value==='feishu'){await openFeishu({taskId:state.selected,taskName:state.result.task.name,count:state.result.matched,query:params().toString()});}
else if(action==='export'){const p=params();p.set('format',$('#export-type').value);location.href=`/api/tasks/${state.selected}/export?${p}`;}
else if(action==='continue-task'){b.disabled=true;await api(`/api/tasks/${b.dataset.id}/continue`,{});await showTask(b.dataset.id);toast('已开始补采，新评论将自动去重并更新分析');}
else if(action==='resume'||action==='pause'){b.disabled=true;await api(`/api/tasks/${b.dataset.id}/${action}`,{});await refresh();await loadResult();render();toast(action==='pause'?'正在暂停，已获取评论会保留':'已继续采集');}
else if(action==='connect'){b.disabled=true;b.textContent='正在打开浏览器…';await api('/api/connect',{platform:b.dataset.platform});await refresh();render();toast('请在打开的浏览器中完成平台登录，再创建或继续采集任务');}
}catch(error){toast(error.message);if(b.isConnected){b.disabled=false;if(b.dataset.action==='connect'){await refresh();render();}}}});
document.addEventListener('input',e=>{if(e.target.id==='keyword-task-search'){state.keywordQuery=e.target.value;state.keywordPage=1;$('#keyword-task-results').innerHTML=keywordResults();$('#keyword-pagination').innerHTML=keywordPagination();}});
document.addEventListener('change',async e=>{try{const t=e.target;if(t.id==='engine-select'){state.engine=t.value;for(const box of document.querySelectorAll('[name=platform]')){box.disabled=t.value==='browser'&&!['douyin','xiaohongshu'].includes(box.value);box.checked=!box.disabled;}}else if(t.id==='platform-filter'){state.filters.platform=t.value;await filtered();}else if(t.id==='category-filter'){state.filters.category=t.value;await filtered();}else if(t.id==='favorite-filter'||t.id==='noise-filter'){state.filters[t.id==='favorite-filter'?'favorite':'noise']=t.checked?'1':'';await filtered();}}catch(error){toast(error.message);}});
document.addEventListener('keydown',async e=>{if(e.target.id==='comment-search'&&e.key==='Enter'){state.filters.q=e.target.value;delete state.filters.word;try{await filtered();}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='task-form')return;e.preventDefault();if(state.busy)return;state.busy=true;$('#form-error').textContent='';$('#submit-task').disabled=true;try{await submit(e.target);}catch(error){$('#form-error').textContent=error.message;}finally{state.busy=false;if($('#submit-task'))$('#submit-task').disabled=false;}});
async function boot(){await refresh();await loadResult();render();}boot().catch(e=>{$('#main').innerHTML=`<section class="panel empty"><h3>工作台暂时无法连接</h3><p>${esc(e.message)}</p><button class="button" data-action="retry">重新连接</button></section>`;});document.addEventListener('click',e=>{if(e.target.dataset.action==='retry')boot().catch(err=>toast(err.message));});
let polling=false;setInterval(async()=>{if(polling||document.querySelector('.keyword-progress[open]')||$('#task-modal').open||$('#detail-modal').open||document.activeElement?.tagName==='INPUT')return;polling=true;try{const before=JSON.stringify([state.tasks.map(t=>[t.id,t.updated_at,t.status]),state.connections,state.activeTaskIds]);await refresh();const after=JSON.stringify([state.tasks.map(t=>[t.id,t.updated_at,t.status]),state.connections,state.activeTaskIds]);if(before!==after){if(state.view==='dashboard')await loadResult();render();}}catch{}finally{polling=false;}},3500);

async function openReplySettings(){
 const config=await api('/api/reply-settings'),d=$('#reply-modal');const labels={pending:'等待发送',sending:'正在发送',sent:'已发送',blocked:'待处理',unknown:'结果待核对',cancelled:'已取消'};
 d.innerHTML=`<div class="modal-head"><div><small>AUTO REPLY</small><h2 id="reply-title">自动回复 · 打招呼用语</h2></div><button type="button" class="icon-button" aria-label="关闭自动回复设置">×</button></div><form id="reply-form"><div class="modal-content"><p class="notice">开启并保存后，只回复新采集且匹配所选需求的评论。每条至少间隔 60 秒；同一评论不重复发送。请先在「数据连接」登录抖音和小红书。</p>
<label class="checkbox"><input name="enabled" type="checkbox" ${config.enabled?'checked':''}>启用自动回复</label>
<fieldset class="reply-options"><legend>回复平台</legend>${['douyin','xiaohongshu'].map(p=>`<label class="checkbox"><input name="replyPlatform" type="checkbox" value="${p}" ${config.platforms.includes(p)?'checked':''}>${names[p]}</label>`).join('')}</fieldset>
<fieldset class="reply-options"><legend>匹配的用户需求</legend>${['求方法','遇到困难','购买咨询','对比选择','场景需求'].map(c=>`<label class="checkbox"><input name="replyCategory" type="checkbox" value="${c}" ${config.categories.includes(c)?'checked':''}>${c}</label>`).join('')}</fieldset>
<label class="field">打招呼用语<textarea name="greeting" maxlength="500" placeholder="填写实际要发送的打招呼内容">${esc(config.greeting)}</textarea></label><p class="help">最多 500 字，所有分析任务共用。修改并保存设置会取消旧的待发送队列，从新采集的评论开始匹配。</p><div class="reply-preview"><small>回复预览</small><p id="reply-preview-text"></p></div>
<div class="section-head reply-record-heading"><h3>最近回复</h3><button class="button small" type="button" id="reply-refresh">刷新记录</button></div><p class="help" id="reply-status"></p><div id="reply-records"></div><p id="reply-message" role="status" aria-live="polite" class="form-error"></p></div><div class="modal-footer"><button class="button" type="button" id="reply-stop">停止自动回复</button><button class="button primary" type="submit">保存设置</button></div></form>`;
 const form=d.querySelector('form'),input=form.elements.greeting,message=d.querySelector('#reply-message'),button=form.querySelector('[type=submit]');let saving=false;
 const records=c=>{d.querySelector('#reply-status').textContent=`${c.enabled?'已启用':'已停止'} · 待发送 ${c.counts.pending||0} · 已发送 ${c.counts.sent||0} · 待处理 ${(c.counts.blocked||0)+(c.counts.unknown||0)}`;d.querySelector('#reply-records').innerHTML=c.records.length?c.records.map(r=>`<div class="reply-record"><span class="tag">${labels[r.status]||'待处理'}</span> ${tag(r.comment.platform)}<p>${esc(r.comment.text)}</p><small>${esc(r.message||'等待发送')} · ${date(r.updated_at)}</small><a class="inline-link" href="${esc(r.comment.source_url)}" target="_blank" rel="noopener noreferrer">查看原作品 ↗</a></div>`).join(''):'<p class="help">还没有发送记录。填好用语并启用后，开始新的采集即可。</p>';};records(config);
 const preview=()=>d.querySelector('#reply-preview-text').textContent=input.value.trim()||'填写用语后，在这里预览';input.addEventListener('input',preview);preview();
 d.querySelector('.icon-button').onclick=()=>{if(!saving)d.close();};d.oncancel=e=>{if(saving)e.preventDefault();};
 d.querySelector('#reply-refresh').onclick=async()=>{try{records(await api('/api/reply-settings'));}catch(e){message.textContent=e.message;}};
 d.querySelector('#reply-stop').onclick=async()=>{try{records(await api('/api/reply-stop',{}));form.elements.enabled.checked=false;message.textContent='自动回复已停止；已发出的请求仍会核对结果。';}catch(e){message.textContent=e.message;}};
 form.onsubmit=async e=>{e.preventDefault();if(saving)return;saving=true;button.disabled=true;message.textContent='正在保存…';try{const data=new FormData(form);const saved=await api('/api/reply-settings',{greeting:input.value,enabled:form.elements.enabled.checked,platforms:data.getAll('replyPlatform'),categories:data.getAll('replyCategory')});input.value=saved.greeting;preview();records(saved);message.textContent=saved.enabled?'已启用，将自动回复新采集且匹配需求的评论。':'设置已保存，自动回复未启用。';}catch(error){message.textContent=error.message;}finally{saving=false;button.disabled=false;}};d.showModal();
}

// Global appearance: one canvas and one animation loop, independent of page renders.
function initAppearance(){
 const root=document.documentElement,select=document.querySelector('#theme-mode'),system=matchMedia('(prefers-color-scheme: dark)'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let mode='system';try{mode=localStorage.getItem('appearance-mode')||'system';}catch{}if(!['system','dark','light'].includes(mode))mode='system';select.value=mode;
 const apply=()=>{root.dataset.theme=mode==='system'?(system.matches?'dark':'light'):mode;const label={system:'跟随系统',dark:'深色模式',light:'浅色模式'}[mode];select.textContent={system:'◐',dark:'☾',light:'☀'}[mode];select.title=label+'（点击切换）';select.setAttribute('aria-label','主题：'+label+'，点击切换');select.value=mode;};select.onclick=()=>{mode={system:'light',light:'dark',dark:'system'}[mode];try{localStorage.setItem('appearance-mode',mode);}catch{}apply();select.dispatchEvent(new Event('change'));};system.addEventListener('change',apply);apply();
 const canvas=document.createElement('canvas');canvas.id='particle-background';canvas.setAttribute('aria-hidden','true');document.body.prepend(canvas);const ctx=canvas.getContext('2d');if(!ctx)return;let points=[],w=0,h=0,frame=0,last=0;
 const resize=()=>{w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);points=Array.from({length:Math.min(65,Math.max(18,Math.floor(w*h/22000)))},()=>({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.7+.6,vx:(Math.random()-.5)*10,vy:Math.random()*-12-3}));};
 const draw=time=>{frame=0;const dt=Math.min((time-last)/1000,.05);last=time;ctx.clearRect(0,0,w,h);ctx.fillStyle=root.dataset.theme==='dark'?'rgba(255,128,66,.4)':'rgba(184,72,25,.45)';for(const p of points){if(!reduce.matches){p.x=(p.x+p.vx*dt+w)%w;p.y=(p.y+p.vy*dt+h)%h;}ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}if(!document.hidden&&!reduce.matches)frame=requestAnimationFrame(draw);};
 const restart=()=>{cancelAnimationFrame(frame);frame=0;last=performance.now();if(!document.hidden)draw(last);};addEventListener('resize',()=>{resize();restart();});document.addEventListener('visibilitychange',restart);reduce.addEventListener('change',restart);system.addEventListener('change',restart);select.addEventListener('change',restart);resize();restart();
}
initAppearance();

const platformIcons={"bilibili": "data:image/x-icon;base64,", "zhihu": "data:image/x-icon;base64,", "weibo": "data:image/x-icon;base64,", "xiaohongshu": "data:image/x-icon;base64,", "kuaishou": "data:image/x-icon;base64,", "douyin": "data:image/x-icon;base64,", "tieba": "data:image/x-icon;base64,"};
function platformIcon(id){return `<img width="36" height="36" src="${platformIcons[id]}" alt="${names[id]}" style="object-fit:contain">`;}

function decorateMetrics(){document.querySelectorAll('.metric').forEach(card=>{const bars=document.createElement('span');bars.className='metric-wave';bars.setAttribute('aria-hidden','true');bars.title='装饰动效';for(let i=0;i<4;i++){const bar=document.createElement('i');bar.style.setProperty('--wave-duration',(1.8+Math.random()*1.6)+'s');bar.style.setProperty('--wave-delay',(-Math.random()*3)+'s');bar.style.setProperty('--wave-low',String(.15+Math.random()*.2));bar.style.setProperty('--wave-high',String(.6+Math.random()*.4));bars.append(bar);}card.append(bars);});}

let insightSignature='',insightObserver,metricAnimationTask='';
function animateInsights(){
 insightObserver?.disconnect();if(!['dashboard','tasks'].includes(state.view)||!state.result){insightSignature='';return;}
 const signature=JSON.stringify([state.view,state.selected,state.filters,state.page,state.tasksPage,state.result.analysis]);if(signature===insightSignature)return;insightSignature=signature;
 const animateMetrics=metricAnimationTask!==state.selected;metricAnimationTask=state.selected;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 for(const [selector] of [['.bar-row'],['.topic']])document.querySelectorAll(selector).forEach((el,i)=>{el.style.setProperty('--entry-delay',`${i*65}ms`);if(!reduced)el.classList.add('insight-enter');});
 const selectors='[data-count],#task-count';
 insightObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const el=entry.target;insightObserver.unobserve(el);const bar=el.closest('.hot-comment,.topic')?.querySelector('.row-progress i');const original=el.dataset.finalText;const matches=[...original.matchAll(/\d[\d,]*/g)];if(reduced||!matches.length){el.textContent=original;if(bar)bar.style.transform='scaleX(1)';continue;}const started=performance.now();const frame=now=>{if(!el.isConnected)return;const progress=Math.min(1,(now-started)/750),ease=1-(1-progress)**3;if(bar)bar.style.transform=`scaleX(${ease})`;let index=0;el.textContent=original.replace(/\d[\d,]*/g,()=>Math.round(Number(matches[index++][0].replaceAll(',',''))*ease).toLocaleString('zh-CN'));if(progress<1)requestAnimationFrame(frame);};requestAnimationFrame(frame);}}, {threshold:.05});
 document.querySelectorAll(selectors).forEach(el=>{if(el.closest('.metric')&&!animateMetrics)return;if(el.closest('.keyword-picker')&&!el.closest('.keyword-selected'))return;el.dataset.finalText=el.textContent;if(!reduced){el.textContent='0';const bar=el.closest('.hot-comment,.topic')?.querySelector('.row-progress i');if(bar)bar.style.transform='scaleX(0)';}insightObserver.observe(el);});
}
let suggestionTimer,suggestionRequest=0;
document.addEventListener('input',e=>{if(e.target.name!=='name'||!e.target.closest('#task-form'))return;clearTimeout(suggestionTimer);const q=e.target.value.trim(),request=++suggestionRequest,list=document.querySelector('#platform-suggestions'),note=document.querySelector('#suggestion-status');list.innerHTML='';if(q.length<2){note.textContent='';return;}suggestionTimer=setTimeout(async()=>{note.textContent='正在获取平台搜索推荐…';try{const result=await api('/api/search-suggestions?q='+encodeURIComponent(q));if(request!==suggestionRequest)return;list.innerHTML=result.suggestions.map(x=>`<option value="${esc(x)}"></option>`).join('');note.textContent=result.message||'';}catch(error){if(request===suggestionRequest)note.textContent=error.message;}},650);});

document.addEventListener('keydown',e=>{if(e.target.matches('[data-action=metric-filter]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});

